-- Cultural identity (15)
insert into public.cultural_profiles (id, name, theme, living_heritage, traveler_values, origins, discoverer_status, source_i_ds, evidence_status, sort_order)
select id, name, theme, living_heritage, traveler_values, origins, discoverer_status, source_i_ds, evidence_status, sort_order from jsonb_populate_recordset(null::public.cultural_profiles, $pamana$[{"id":"oriental_mindoro_puerto_galera","name":"Puerto Galera","theme":"Iraya-Mangyan nito weaving","living_heritage":"Basket-making and the sharing of craft knowledge are documented in the cited Iraya-Mangyan community material. Specific patterns and demonstrations require maker consent.","traveler_values":["Respect named-community attribution","Care for linked land and water habitats"],"origins":"The cited community material records Iraya-Mangyan artisans and livelihoods connected to land and sea. It does not date the earliest habitation or identify one discoverer. Existing communities are not made newly discovered by an outsider’s arrival.","discoverer_status":"The available source material does not establish a single discoverer. Administrative dates, name stories, and outsider arrival do not establish the beginning of habitation.","source_i_ds":["pg_unesco","pg_weaving","pg_ayala"],"evidence_status":"Inherited, attributed material; fresh verification and community review remain pending.","sort_order":0},{"id":"oriental_mindoro_san_teodoro","name":"San Teodoro","theme":"Nito weaving and coconut-based work","living_heritage":"The cited material describes Iraya craft knowledge and coconut processing. These are documented aspects of local life, not a claim that every household follows one tradition.","traveler_values":["Respect community differences","Value careful work and cooperation"],"origins":"The history records Subaan as an earlier name and municipal reestablishment effective 1 January 1929. Reestablishment concerns administration; it does not mean people first settled there in 1929.","discoverer_status":"The available source material does not establish a single discoverer. Administrative dates, name stories, and outsider arrival do not establish the beginning of habitation.","source_i_ds":["enterprise","iraya_craft","st_history","act3498","ppdo_history"],"evidence_status":"Inherited, attributed material; fresh verification and community review remain pending.","sort_order":1},{"id":"oriental_mindoro_baco","name":"Baco","theme":"Local name accounts and calamansi growing","living_heritage":"The paco name account preserves remembered community narrative. Farmer organizations are documented in calamansi planting support. Iraya and Alangan attribution must be kept specific.","traveler_values":["Tell local stories with attribution","Respect distinct communities"],"origins":"Act 3498 reestablished Baco and San Teodoro separately effective 1 January 1929. Earlier research also names Iraya and Alangan communities in Baco. The law does not establish the first arrival of people or erase those communities’ histories.","discoverer_status":"The available source material does not establish a single discoverer. Administrative dates, name stories, and outsider arrival do not establish the beginning of habitation.","source_i_ds":["farm_report","baco_history","act3498","mhc_groups"],"evidence_status":"Inherited, attributed material; fresh verification and community review remain pending.","sort_order":2},{"id":"oriental_mindoro_calapan_city","name":"Calapan City","theme":"Local food-making and sharing","living_heritage":"The city material highlights local delicacies and food-sharing as expressions of community identity. Farming and commerce also form part of city life.","traveler_values":["Share thoughtfully","Value the work behind everyday food"],"origins":"Calapan’s 21 March 1998 cityhood plebiscite concerns city status. Its community history did not begin with cityhood. Earlier capital-transfer dates conflict in the research notes, so no first-settlement or transfer date is invented here.","discoverer_status":"The available source material does not establish a single discoverer. Administrative dates, name stories, and outsider arrival do not establish the beginning of habitation.","source_i_ds":["calapan","farm_report","calapan_food","calapan_history","ppdo_history"],"evidence_status":"Inherited, attributed material; fresh verification and community review remain pending.","sort_order":3},{"id":"oriental_mindoro_naujan","name":"Naujan","theme":"Freshwater livelihoods and varied community beliefs","living_heritage":"Fishing connects community work with the shared lake landscape. Historical records describe parts of religious life; these do not represent every resident’s beliefs.","traveler_values":["Care for shared water","Respect different beliefs"],"origins":"The inherited material does not establish Naujan’s earliest settlement date. Earlier notes warn that a claim about imported pottery cannot by itself identify the ethnicity of residents. Objects may travel through trade; archaeological context and specialist evidence are needed.","discoverer_status":"The available source material does not establish a single discoverer. Administrative dates, name stories, and outsider arrival do not establish the beginning of habitation.","source_i_ds":["lake_fisheries","naujan_history"],"evidence_status":"Inherited, attributed material; fresh verification and community review remain pending.","sort_order":4},{"id":"oriental_mindoro_victoria","name":"Victoria","theme":"Fruit-growing knowledge and remembered place names","living_heritage":"Rice and varied fruits support documented farm livelihoods. The Borbocolon account preserves a remembered relationship with water; it remains a local account.","traveler_values":["Care for soil and water","Distinguish stories from proven events"],"origins":"Victoria was formed from territory formerly belonging to Naujan in 1953, according to the municipal history. This records a jurisdictional change; it does not establish that the territory was previously uninhabited.","discoverer_status":"The available source material does not establish a single discoverer. Administrative dates, name stories, and outsider arrival do not establish the beginning of habitation.","source_i_ds":["victoria_up","victoria_history"],"evidence_status":"Inherited, attributed material; fresh verification and community review remain pending.","sort_order":5},{"id":"oriental_mindoro_socorro","name":"Socorro","theme":"Mixed-crop farming and settlement memory","living_heritage":"Calamansi, rambutan, coffee, and bananas appear in the livelihood briefing. Catiningan and the naming account connect local memory with the town’s development.","traveler_values":["Cooperate around shared resources","Keep historical attribution accurate"],"origins":"Republic Act 3609 created Socorro from territory formerly belonging to Pola in 1963, according to the inherited legal citation. Catiningan appears in the local account. Creation of a municipality does not date the first habitation of its territory.","discoverer_status":"The available source material does not establish a single discoverer. Administrative dates, name stories, and outsider arrival do not establish the beginning of habitation.","source_i_ds":["ppdo_history","socorro_lgu","socorro_law"],"evidence_status":"Inherited, attributed material; fresh verification and community review remain pending.","sort_order":6},{"id":"oriental_mindoro_pola","name":"Pola","theme":"Recorded nipa weaving and fishing livelihoods","living_heritage":"Nipa weaving is recorded in the municipal history alongside farming and fishing. The record does not establish the extent of current practice or authorize copying a maker’s technique.","traveler_values":["Respect makers and their work","Care for waterways"],"origins":"The historical account places Pola’s town center at a river estuary. Farming, fishing, and nipa weaving connect community life to land and water. The record supports this settlement setting, not a precise first-inhabitant date.","discoverer_status":"The available source material does not establish a single discoverer. Administrative dates, name stories, and outsider arrival do not establish the beginning of habitation.","source_i_ds":["pola_history"],"evidence_status":"Inherited, attributed material; fresh verification and community review remain pending.","sort_order":7},{"id":"oriental_mindoro_pinamalayan","name":"Pinamalayan","theme":"Rainbow storytelling and banana-chip enterprise","living_heritage":"The rainbow narrative is a recorded origin legend. Banana-chip making is a documented food enterprise. No pottery tradition is inferred from a monument.","traveler_values":["Preserve stories honestly","Recognize practical food-making skills"],"origins":"The quick-facts account dates a town-seat transfer to 1916 and describes a planned center. A transfer implies an earlier town-seat location; the account does not establish the first habitation of the municipality. The date still needs archival corroboration.","discoverer_status":"The available source material does not establish a single discoverer. Administrative dates, name stories, and outsider arrival do not establish the beginning of habitation.","source_i_ds":["pin_facts","pin_history","pin_lgu"],"evidence_status":"Inherited, attributed material; fresh verification and community review remain pending.","sort_order":8},{"id":"oriental_mindoro_gloria","name":"Gloria","theme":"Bamboo craft training and banana-chip processing","living_heritage":"DTI-supported bamboo handicraft training and banana-chip processing are documented. Contemporary skills training is living culture; it is not described as an ancient ritual.","traveler_values":["Practice patience and cooperation","Recognize skills without inventing antiquity"],"origins":"The inherited summary describes settlement around Tambong in the early twentieth century and mentions Maligaya. The chronology has not been reverified. Accounts of arriving migrants must not imply that the land had no earlier inhabitants.","discoverer_status":"The available source material does not establish a single discoverer. Administrative dates, name stories, and outsider arrival do not establish the beginning of habitation.","source_i_ds":["enterprise","gloria_craft","gloria_history","ppdo_history"],"evidence_status":"Inherited, attributed material; fresh verification and community review remain pending.","sort_order":9},{"id":"oriental_mindoro_bansud","name":"Bansud","theme":"Banana livelihoods and the basud oral account","living_heritage":"Bananas are part of documented agricultural identity. The basud or delta explanation remains an oral account with unresolved language attribution.","traveler_values":["Respect language attribution","Value farm work and shared land"],"origins":"The compiled history records Bansud as formerly part of Bongabong. The earlier research notes identify Republic Act 2514 as a legal lead to check, but do not establish a verified precise creation or first-settlement date in this briefing.","discoverer_status":"The available source material does not establish a single discoverer. Administrative dates, name stories, and outsider arrival do not establish the beginning of habitation.","source_i_ds":["bansud_agri","bansud_history","ppdo_history"],"evidence_status":"Inherited, attributed material; fresh verification and community review remain pending.","sort_order":10},{"id":"oriental_mindoro_bongabong","name":"Bongabong","theme":"Coconut livelihoods and remembered name accounts","living_heritage":"Coconut plantations on coastal plains and a Binago-related name explanation appear in the inherited history. Distinct community narratives require their own contributors and credits.","traveler_values":["Credit the right contributors","Care for land and river systems"],"origins":"The compiled history connects earlier settlement and name accounts with Bongabong’s coastal landscape. Some political dates conflict between summaries. The material does not establish a sole discoverer or a precise earliest-settlement date.","discoverer_status":"The available source material does not establish a single discoverer. Administrative dates, name stories, and outsider arrival do not establish the beginning of habitation.","source_i_ds":["bong_history","ppdo_history","mhc_groups"],"evidence_status":"Inherited, attributed material; fresh verification and community review remain pending.","sort_order":11},{"id":"oriental_mindoro_roxas","name":"Roxas","theme":"Farm knowledge and the Paclasan name account","living_heritage":"Farmer organizations received calamansi planting support. The palasan-palm account links remembered naming with plants and land; it is not a proven sole origin.","traveler_values":["Respect community memory","Value care for crops and soils"],"origins":"The earlier settlement of Paclasan is linked to Roxas’s development in the compiled history. A historical settlement name is useful evidence, but the current briefing does not establish the first inhabitants, a sole discoverer, or an exact first-settlement date.","discoverer_status":"The available source material does not establish a single discoverer. Administrative dates, name stories, and outsider arrival do not establish the beginning of habitation.","source_i_ds":["farm_report","roxas_history"],"evidence_status":"Inherited, attributed material; fresh verification and community review remain pending.","sort_order":12},{"id":"oriental_mindoro_mansalay","name":"Mansalay","theme":"Hanunoo Mangyan ambahan","living_heritage":"The NCCA citation links Ginaw Bilog with Mansalay and ambahan, whose lines have seven syllables. Cultural association does not grant permission to reproduce verses, recordings, or motifs.","traveler_values":["Respect culture bearers and permissions","Keep Hanunoo Mangyan attribution specific"],"origins":"Act 3498 reestablished Mansalay and Bulalacao separately effective 1 January 1929. This concerns municipal administration, not the beginning of Indigenous community life or a claim that an outsider discovered uninhabited land.","discoverer_status":"The available source material does not establish a single discoverer. Administrative dates, name stories, and outsider arrival do not establish the beginning of habitation.","source_i_ds":["farm_report","ambahan_ncca","ambahan_form","act3498"],"evidence_status":"Inherited, attributed material; fresh verification and community review remain pending.","sort_order":13},{"id":"oriental_mindoro_bulalacao","name":"Bulalacao","theme":"Seaweed-noodle enterprise and the bird-name myth","living_heritage":"A cooperative’s seaweed or kelp noodle production is documented. The town history labels the bird-related origin account as a myth, preserving storytelling without claiming historical proof.","traveler_values":["Value cooperative practical skills","Distinguish myth from documented history"],"origins":"Act 3498 reestablished Bulalacao and Mansalay separately effective 1 January 1929. The proposed identification of an older place with Mait remains a hypothesis. It is not settled proof of a tenth-century settlement continuous with the present municipality.","discoverer_status":"The available source material does not establish a single discoverer. Administrative dates, name stories, and outsider arrival do not establish the beginning of habitation.","source_i_ds":["enterprise","bulalacao_history","act3498","ppdo_history"],"evidence_status":"Inherited, attributed material; fresh verification and community review remain pending.","sort_order":14}]$pamana$::jsonb)
on conflict (id) do nothing;

-- Research notes (15)
insert into public.research_notes (id, place_i_d, title, statement, evidence_label, verification_needed, source_i_ds, fact_quiz_eligible, sort_order)
select id, place_i_d, title, statement, evidence_label, verification_needed, source_i_ds, fact_quiz_eligible, sort_order from jsonb_populate_recordset(null::public.research_notes, $pamana$[{"id":"puerto-galera-craft-context","place_i_d":"oriental_mindoro_puerto_galera","title":"Community attribution for weaving","statement":"The earlier research summary links nito weaving with Iraya-Mangyan artisans in Talipanan. Current practitioner accounts, the transmission of skills, and permission to reproduce particular designs have not been independently checked in this update.","evidence_label":"Inherited research summary; current details unverified","verification_needed":"Read the cited program reports and obtain named-community review before adding maker biographies, demonstrations, or distinctive patterns.","source_i_ds":["pg_ayala","pg_weaving"],"fact_quiz_eligible":false,"sort_order":0},{"id":"san-teodoro-name-versions","place_i_d":"oriental_mindoro_san_teodoro","title":"Competing name-change explanations","statement":"Earlier research notes flag a three-Theodores explanation of the town’s name as uncertain. This app does not establish that explanation as the origin of the name or identify a confirmed founder from it.","evidence_label":"Unverified name-origin account","verification_needed":"Locate the original account, compare local oral-history versions, and distinguish naming stories from administrative records.","source_i_ds":["st_history","ppdo_history"],"fact_quiz_eligible":false,"sort_order":1},{"id":"baco-community-attribution","place_i_d":"oriental_mindoro_baco","title":"Community names need precise attribution","statement":"The earlier research summary names Iraya and Alangan communities in accounts of Baco. Community presence does not establish that every practice or design belongs to both communities; the relevant passages and present-day attribution still need review.","evidence_label":"Inherited community-presence claim; attribution pending","verification_needed":"Check the historical passages and community-led sources separately; do not substitute Hanunó’o motifs for Iraya or Alangan material.","source_i_ds":["baco_history","mhc_groups"],"fact_quiz_eligible":false,"sort_order":2},{"id":"calapan-capital-chronology","place_i_d":"oriental_mindoro_calapan_city","title":"Capital-transfer chronology remains unresolved","statement":"Earlier editorial notes report conflicting capital-transfer dates. No specific transfer date is added here as established history; cityhood and a change in administrative capital must not be treated as the same event.","evidence_label":"Reported source conflict; dates unresolved","verification_needed":"Compare original administrative instruments and dated archival records before adopting a transfer chronology.","source_i_ds":["calapan_history","ppdo_history"],"fact_quiz_eligible":false,"sort_order":3},{"id":"naujan-settlement-inference","place_i_d":"oriental_mindoro_naujan","title":"Objects are not proof of a community’s identity","statement":"Earlier research notes caution against concluding that inhabitants were Chinese merely from a claim about imported pottery. The underlying archaeological evidence has not been checked here, and no ethnic identity or earliest-settlement date is established by this note.","evidence_label":"Unverified archaeological inference","verification_needed":"Find excavation context, dating evidence, and specialist interpretation. Distinguish trade in objects from conclusions about the identity of residents.","source_i_ds":["naujan_history"],"fact_quiz_eligible":false,"sort_order":4},{"id":"victoria-fruit-description","place_i_d":"oriental_mindoro_victoria","title":"A descriptive label is not an exclusive designation","statement":"The earlier research summary describes Victoria as a fruit basket. The wording is not treated here as a formal, exclusive, or current statistical designation, and it does not establish that every pictured fruit is a major local crop.","evidence_label":"Inherited descriptive wording; scope unverified","verification_needed":"Read the agricultural studies, retain their dates, and ask growers about the varieties and activities represented.","source_i_ds":["victoria_up","victoria_history"],"fact_quiz_eligible":false,"sort_order":5},{"id":"socorro-creation-conflict","place_i_d":"oriental_mindoro_socorro","title":"1962 and 1963: compare the records","statement":"Earlier research notes identify a conflict: one provincial summary gives 1962, while the cited Republic Act 3609 and LGU account identify 1963. This is presented as a source-comparison lead; the original legal text has not been retrieved again in this update.","evidence_label":"Inherited conflicting dates; primary citation awaits rechecking","verification_needed":"Read the Act’s approval and effectivity provisions and compare them with the LGU chronology; do not choose a date by majority vote among websites.","source_i_ds":["socorro_law","ppdo_history","socorro_lgu"],"fact_quiz_eligible":false,"sort_order":6},{"id":"pola-current-craft-practice","place_i_d":"oriental_mindoro_pola","title":"Recorded craft and current practice differ","statement":"The prior research records nipa weaving, but current practitioners, techniques, and the extent of present-day practice were not verified. A historical mention does not prove that every household practices the craft today.","evidence_label":"Historical citation; current practice unverified","verification_needed":"Read the historical account and seek consent-based maker review before illustrating a specific technique or naming practitioners.","source_i_ds":["pola_history"],"fact_quiz_eligible":false,"sort_order":7},{"id":"pinamalayan-planning-records","place_i_d":"oriental_mindoro_pinamalayan","title":"Town-planning chronology needs corroboration","statement":"The earlier quick-facts summary links the town-seat transfer with 1916 and describes a planned center. These details still need comparison with dated planning records; the rainbow account remains a separate local legend.","evidence_label":"Inherited planning summary; chronology not reverified","verification_needed":"Locate dated municipal planning or administrative records and keep the town-seat chronology separate from name-origin storytelling.","source_i_ds":["pin_facts","pin_history"],"fact_quiz_eligible":false,"sort_order":8},{"id":"gloria-settlement-context","place_i_d":"oriental_mindoro_gloria","title":"Settlement accounts do not imply empty land","statement":"The earlier research summary connects Gloria’s development with Tambong and Maligaya and a former connection to Pinamalayan. The detailed settlement chronology has not been reverified; accounts of arriving migrants must not imply that the land had no earlier inhabitants.","evidence_label":"Inherited settlement summary; chronology incomplete","verification_needed":"Compare dated local histories with evidence about existing communities, land use, and migration before writing a founding narrative.","source_i_ds":["gloria_history","ppdo_history"],"fact_quiz_eligible":false,"sort_order":9},{"id":"bansud-name-and-law","place_i_d":"oriental_mindoro_bansud","title":"Name meaning, language, and creation date","statement":"Earlier notes leave the specific language and community attribution of the basud name account unresolved. They also flag Republic Act 2514 as a lead to check before teaching a precise municipal creation date. Neither missing detail is supplied as a confirmed fact here.","evidence_label":"Oral-account attribution and legal lead pending","verification_needed":"Locate the original legal instrument and a credible language or community source; do not infer a particular Mangyan language from a generic label.","source_i_ds":["bansud_history","ppdo_history"],"fact_quiz_eligible":false,"sort_order":10},{"id":"bongabong-political-chronology","place_i_d":"oriental_mindoro_bongabong","title":"Political dates need source comparison","statement":"Earlier editorial notes identify disagreements between municipal and portal histories about some political dates. No disputed date is adopted here. Buhid and Bangon narratives also require separate contributor attribution rather than being blended into one community story.","evidence_label":"Reported chronological conflict and attribution gaps","verification_needed":"Compare dated administrative records and named-community accounts before expanding the local political or cultural narrative.","source_i_ds":["bong_history","ppdo_history","mhc_groups"],"fact_quiz_eligible":false,"sort_order":11},{"id":"roxas-name-account-scope","place_i_d":"oriental_mindoro_roxas","title":"Paclasan and the palasan account","statement":"The inherited material connects Roxas with Paclasan and preserves a palasan-palm name account. This update has not established a sole origin, a confirmed first-settlement date, or the original language attribution of that explanation.","evidence_label":"Inherited local name account; origin not established","verification_needed":"Compare the original history passages, older administrative records, and local accounts before presenting a single origin story.","source_i_ds":["roxas_history"],"fact_quiz_eligible":false,"sort_order":12},{"id":"mansalay-cultural-context","place_i_d":"oriental_mindoro_mansalay","title":"Association does not grant permission to reproduce","statement":"The inherited NCCA citation connects Ginaw Bilog, Mansalay, and ambahan. That association does not establish permission to reproduce particular verses, translations, recordings, or motifs; none of those materials is newly introduced through this note.","evidence_label":"Inherited institutional citation; reuse permissions unconfirmed","verification_needed":"Read the cited cultural account and arrange community-led review, attribution, and appropriate permissions before reproducing expressive material.","source_i_ds":["ambahan_ncca","ambahan_form"],"fact_quiz_eligible":false,"sort_order":13},{"id":"bulalacao-mait-hypothesis","place_i_d":"oriental_mindoro_bulalacao","title":"Mait and early settlement: a hypothesis","statement":"Earlier research notes describe the identification of an old town with Mait as a hypothesis, not settled proof of a tenth-century settlement. This app does not present that identification or date as an established origin for Bulalacao.","evidence_label":"Unverified historical identification hypothesis","verification_needed":"Locate the underlying historical and archaeological arguments, check dates and geographic identification, and compare scholarly alternatives before asserting continuity with a present-day municipality.","source_i_ds":["bulalacao_history","ppdo_history"],"fact_quiz_eligible":false,"sort_order":14}]$pamana$::jsonb)
on conflict (id) do nothing;

-- Local story guides (15)
insert into public.municipal_guides (id, name, sprite_name, token_name, sprite_type, palette, token_image, passport_image, sprite_image, sort_order)
select id, name, sprite_name, token_name, sprite_type, palette, token_image, passport_image, sprite_image, sort_order from jsonb_populate_recordset(null::public.municipal_guides, $pamana$[{"id":"oriental_mindoro_puerto_galera","name":"Puerto Galera","sprite_name":"Harbor lanternfish","token_name":"Nito basket token","sprite_type":"static_fictional_story_guide","palette":"deep indigo, sea turquoise and pale raffia","token_image":"municipal/puerto_galera_token.webp","passport_image":"municipal/puerto_galera_passport.webp","sprite_image":"municipal/puerto_galera_sprite.webp","sort_order":0},{"id":"oriental_mindoro_san_teodoro","name":"San Teodoro","sprite_name":"Cloud gardener","token_name":"River-drop token","sprite_type":"static_fictional_story_guide","palette":"sky cyan, cool slate and white","token_image":"municipal/san_teodoro_token.webp","passport_image":"municipal/san_teodoro_passport.webp","sprite_image":"municipal/san_teodoro_sprite.webp","sort_order":1},{"id":"oriental_mindoro_baco","name":"Baco","sprite_name":"Fern stone guardian","token_name":"Paco fern token","sprite_type":"static_fictional_story_guide","palette":"forest emerald, dark plum and copper","token_image":"municipal/baco_token.webp","passport_image":"municipal/baco_passport.webp","sprite_image":"municipal/baco_sprite.webp","sort_order":2},{"id":"oriental_mindoro_calapan_city","name":"Calapan City","sprite_name":"Parcel messenger","token_name":"Trading-scale token","sprite_type":"static_fictional_story_guide","palette":"brick coral, warm cream and brass","token_image":"municipal/calapan_city_token.webp","passport_image":"municipal/calapan_city_passport.webp","sprite_image":"municipal/calapan_city_sprite.webp","sort_order":3},{"id":"oriental_mindoro_naujan","name":"Naujan","sprite_name":"Reed bird","token_name":"Fish observation lens","sprite_type":"static_fictional_story_guide","palette":"lake cobalt, silver and reed green","token_image":"municipal/naujan_token.webp","passport_image":"municipal/naujan_passport.webp","sprite_image":"municipal/naujan_sprite.webp","sort_order":4},{"id":"oriental_mindoro_victoria","name":"Victoria","sprite_name":"Orchard snail","token_name":"Rambutan token","sprite_type":"static_fictional_story_guide","palette":"rambutan crimson, leaf lime and honey","token_image":"municipal/victoria_token.webp","passport_image":"municipal/victoria_passport.webp","sprite_image":"municipal/victoria_sprite.webp","sort_order":5},{"id":"oriental_mindoro_socorro","name":"Socorro","sprite_name":"Coffee seedling","token_name":"Coffee-cherry token","sprite_type":"static_fictional_story_guide","palette":"espresso brown, burnt orange and cream","token_image":"municipal/socorro_token.webp","passport_image":"municipal/socorro_passport.webp","sprite_image":"municipal/socorro_sprite.webp","sort_order":6},{"id":"oriental_mindoro_pola","name":"Pola","sprite_name":"Folded-leaf crab","token_name":"Nipa-panel token","sprite_type":"static_fictional_story_guide","palette":"nipa olive, clay terracotta and sand","token_image":"municipal/pola_token.webp","passport_image":"municipal/pola_passport.webp","sprite_image":"municipal/pola_sprite.webp","sort_order":7},{"id":"oriental_mindoro_pinamalayan","name":"Pinamalayan","sprite_name":"Rainbow kite","token_name":"Rainbow-pot token","sprite_type":"static_fictional_story_guide","palette":"rainbow jewel tones with violet and yellow dominant","token_image":"municipal/pinamalayan_token.webp","passport_image":"municipal/pinamalayan_passport.webp","sprite_image":"municipal/pinamalayan_sprite.webp","sort_order":8},{"id":"oriental_mindoro_gloria","name":"Gloria","sprite_name":"Bamboo sprout dragon","token_name":"Bamboo craft-box token","sprite_type":"static_fictional_story_guide","palette":"bamboo jade, warm ivory and tangerine","token_image":"municipal/gloria_token.webp","passport_image":"municipal/gloria_passport.webp","sprite_image":"municipal/gloria_sprite.webp","sort_order":9},{"id":"oriental_mindoro_bansud","name":"Bansud","sprite_name":"Banana blossom","token_name":"Banana-bunch token","sprite_type":"static_fictional_story_guide","palette":"banana gold, magenta and charcoal","token_image":"municipal/bansud_token.webp","passport_image":"municipal/bansud_passport.webp","sprite_image":"municipal/bansud_sprite.webp","sort_order":10},{"id":"oriental_mindoro_bongabong","name":"Bongabong","sprite_name":"Coconut drummer","token_name":"Coconut-work token","sprite_type":"static_fictional_story_guide","palette":"coconut chestnut, mint and milk white","token_image":"municipal/bongabong_token.webp","passport_image":"municipal/bongabong_passport.webp","sprite_image":"municipal/bongabong_sprite.webp","sort_order":11},{"id":"oriental_mindoro_roxas","name":"Roxas","sprite_name":"Harvest cart","token_name":"Rice-sheaf token","sprite_type":"static_fictional_story_guide","palette":"rice straw gold, navy and pale peach","token_image":"municipal/roxas_token.webp","passport_image":"municipal/roxas_passport.webp","sprite_image":"municipal/roxas_sprite.webp","sort_order":12},{"id":"oriental_mindoro_mansalay","name":"Mansalay","sprite_name":"Bookwing moth","token_name":"Bamboo writing token","sprite_type":"static_fictional_story_guide","palette":"amethyst purple, muted teal and parchment","token_image":"municipal/mansalay_token.webp","passport_image":"municipal/mansalay_passport.webp","sprite_image":"municipal/mansalay_sprite.webp","sort_order":13},{"id":"oriental_mindoro_bulalacao","name":"Bulalacao","sprite_name":"Seaweed seahorse","token_name":"Seaweed-noodle token","sprite_type":"static_fictional_story_guide","palette":"seafoam aqua, sunset peach and seaweed burgundy","token_image":"municipal/bulalacao_token.webp","passport_image":"municipal/bulalacao_passport.webp","sprite_image":"municipal/bulalacao_sprite.webp","sort_order":14}]$pamana$::jsonb)
on conflict (id) do nothing;

