-- Shop: power-ups (7)
insert into public.shop_powerups (id, name, price, description, sort_order)
select id, name, price, description, sort_order from jsonb_populate_recordset(null::public.shop_powerups, $pamana$[{"id":"forcefield","name":"Buddy Forcefield","price":200,"description":"Blocks 5 dangerous hits and repels hazards.","sort_order":0},{"id":"treasure_magnet","name":"Treasure Magnet","price":120,"description":"Attracts the next 15 coins, stars, and destination items.","sort_order":1},{"id":"buddy_rush","name":"Buddy Rush","price":220,"description":"Move faster and reach rewards more easily for 12 seconds.","sort_order":2},{"id":"lucky_star","name":"Lucky Star","price":130,"description":"The next 10 eligible rewards count twice.","sort_order":3},{"id":"paw_burst","name":"Heritage Burst","price":160,"description":"Clears active hazards from the route.","sort_order":4},{"id":"paw_counter","name":"Guardian Counter","price":180,"description":"Catches and reflects the next 3 enemy projectiles.","sort_order":5},{"id":"buddy_instinct","name":"Buddy Instinct","price":260,"description":"Automatically dodges danger and catches rewards for 20 seconds.","sort_order":6}]$pamana$::jsonb)
on conflict (id) do nothing;

